{

	isVersionLater : function(target) {
		if (!ntf.context.appVersion) return false;
		if (!target) return false;

		var va = ntf.context.appVersion.split('.');
		var ta = target.split('.');

		//alert(va + '  ||  ' + ta);

		var zeroPadF = function(item) {
			item = item.replace(/\D/g, '');	 // remove all non digits
			var vpi = parseInt(item);
			return ('00000000' + vpi).slice(-8);
		};

		var verz = va.map(zeroPadF).join('.');
		var targz = ta.map(zeroPadF).join('.');

		//alert(verz + '  ||  ' + targz);

		var isGreater = (verz > targz);

		return isGreater;

	},

	mainRule : function(ntf, callbackContinue, callbackSuccess, callbackError) {
		var main = this;
		var ft3 = ntf.scope;
		var doc = ntf.document;

		// -----------------------------------------------------------------
		// Initialise
		// -----------------------------------------------------------------
		ntf.logger.info('Ruleset "RuleSet Onload" started, run #' + ntf.runCount);
		if (ntf.runCount === 1) {
			// Do initial stuff
			var event = doc.event;
			var sh = ntf.document.systemHeader;
			ntf.isNew = (sh && sh.createdDate) ? false : true;

			ntf.hasRun = {};
		}

		// bind Id to button
		var selector = 'button:contains("TestMe()")';
		var jqF = function() {
			$(selector).text('Test Me').attr('id', 'cmdTestMe');
		};

		window.setTimeout(jqF, 100);

		// -----------------------------------------------------------------
		// Show Old Template Link button
		// -----------------------------------------------------------------
		if (
			ntf.document.template && ntf.document.template.length
		) {
			var fields = [
				'shTemplateLinkStart',
				'template',
				'cmdAppTagger',
				'event',
				'cmdLinkOldTemplates',
				'shTemplateLinkEnd'
			];
			fields.forEach(function(field) {
				ft3.showField(field, true);
			});

		}

		// -----------------------------------------------------------------
		// Update "name" to old "objectEventDescriptor" if blank
		// -----------------------------------------------------------------
		if (!ntf.document.name) {
			ntf.document.name = ntf.document.objectEventDescriptor;
		}

		// -----------------------------------------------------------------
		// Rule ShowTemplates
		// -----------------------------------------------------------------
		if (
			!ntf.hasRun.showLinkedTemplates
		) {
			ntf.hasRun.showLinkedTemplates = true;
			ntf.logger.info('In rule ShowTemplates');

			var docId = ntf.document.documentId;
			var uid = ntf.user.documentId;

			var eqry = {
				"sort" : [
					{"name" : "asc"},
					{"systemHeader.summaryName" : "asc"}
				],
				"query": {"bool" : {
					"filter": [
						{"terms" : {"systemHeader.systemType" : ["template","schedule"]}}
					],
					"should" : [
						{"term" : {"preRenderClientRuleRel.documentId" : docId}},	
						{"term" : {"onLoadClientRuleRel.documentId" : docId}},	
						{"term" : {"onFieldChangeClientRuleRel.documentId" : docId}},	
						{"term" : {"preSaveClientRuleRel.documentId" : docId}},	
						{"term" : {"preSaveServerRuleRel.documentId" : docId}},	
						{"term" : {"postSaveServerRuleRel.documentId" : docId}},
						{"term" : {"rulesetRel.documentId" : docId}}
					],
					"minimum_should_match" : 1
				}}
			};
			eqry.size = 1000;

			ft3.findDocumentsByElastic(eqry, uid, function(err, result) {
				if (err) {
					ft3.ModalService.openModal({
						title : 'Show Linked Templates',
						text : 'ElasticSearch Query error: please check query.',
						type : 'error'
					});
				}
				else {
					var count = result.data.hits.total;

					var arrTemplates = result.data.hits.hits.map(function(hit){return hit._source});
					arrTemplates.sort((a,b) => {
						var atitle = (a.name || a.systemHeader.summaryName || 'zzzz').toLowerCase();
						var btitle = (b.name || b.systemHeader.summaryName || 'zzzz').toLowerCase();
						return atitle < btitle ? -1 : 1;
					});

					var arrTitleLinks = arrTemplates.map(function(tdoc) {
						var name = tdoc.name || tdoc.systemHeader.summaryName;
						name = $('<div/>').text(name).html();	   // html-ize it

						var link = '<a class="linkButton" href="/form/' + tdoc.documentId + '" target="_blank">'
								+ name + '</a>';
						return link;
					});
					var listz = arrTitleLinks.join('');
					ntf.logger.info('listz ' + listz );

					var delayF = function() {
						$('div#divTemplatesLinked').html(listz);
					};
					window.setTimeout(delayF, 1000);


				}
				callbackContinue(ntf);
			});
			return;
		}

		// -----------------------------------------------------------------
		// Show Overload
		// -----------------------------------------------------------------
		var temps = ntf.document.ruleSetDSL && ntf.document.ruleSetDSL.split('\n');
		var nbrLines = temps.length;
		var isOversize = (nbrLines > 2000);
		ft3.showField('oversizeWarning', isOversize);

		// -----------------------------------------------------------------
		// Show Revert button
		// -----------------------------------------------------------------
		ntf.logger.info('ntf.isNew: ' + ntf.isNew);
		if (
			ntf.isNew	
		) {
			ft3.showField('cmdJsonStarter',true);
			ft3.showField('cmdLinkedTemplates', false);
			ft3.showField('buttonLinkToTemplates', false);
			ft3.showField('shNoLinkOnNew', true);
			ft3.showField('shTemplatesLinked', false);
		}

		// -----------------------------------------------------------------
		// Convert .note to .rulesetNote
		// -----------------------------------------------------------------
		if (
			ntf.document.note	
		) {
			ntf.logger.info('Converting "note" to "rulesetNote"');
			ntf.document.rulesetNote = ntf.document.note;
		}

		// -----------------------------------------------------------------
		// Finally
		// -----------------------------------------------------------------
		ntf.logger.info('Ruleset "RuleSet Onload" completed ok');		
		callbackSuccess();
	}
}

// RuleSet: Ruleset - OnFieldChange
// Updated by: admin@example.com 2021-11-11 11:44:38 +11:00
{
	// =================================================================
	// Please Note
	// This ruleset should be maintained as a non-JayRule ruleset.
	// Otherwise, should there be any glitches, it then becomes difficult to remedy as
	// the extra layers of broken customisation get in the way.
	// pdexter 2020-03-09
	// =================================================================

	// =================================================================
	// MAIN RULE
	// =================================================================
	mainRule : function(ntf, callbackContinue, callbackSuccess, callbackError) {
		var main = this;
		var ft3 = ntf.scope;
		var doc = ntf.document;
		var fieldChanged = ntf.context.fieldChanged;

		// -----------------------------------------------------------------
		// Initialise
		// -----------------------------------------------------------------
		ntf.logger.info('Ruleset "RuleSet OnFieldChange" started, run #' + ntf.runCount);			
		if (ntf.runCount === 1) {
			// Do initial stuff
			var event = doc.event;
			var sh = ntf.document.systemHeader;
			ntf.isNew = (sh && sh.createdDate) ? false : true;
			ntf.isClientEvent = (event === 'OnLoad' || event === 'OnFieldChange' || event === 'PreSave');

			ntf.userId = ntf.user.documentId;
			ntf.hasRun = {};
		}

		// Load Sweetalert manually
		if (!ft3.ModalService.initialised && ft3.lazyLoader) {
			ft3.lazyLoader.load({name: 'swal', files: [
				"https://cdnjs.cloudflare.com/ajax/libs/limonte-sweetalert2/6.6.2/sweetalert2.min.js",
				"https://cdnjs.cloudflare.com/ajax/libs/limonte-sweetalert2/6.6.2/sweetalert2.min.css"
			]})
			.then(function() {
				// Do something with the module.
				ft3.ModalService.openModal = swal;
				ft3.ModalService.initialised = true;
				callbackContinue(ntf);
			});
			return;
		}

		// -----------------------------------------------------------------------------------------
		// Load moment
		// -----------------------------------------------------------------------------------------
		if (!ft3.moment) {
			ft3.lazyLoader.load({ name: 'moment', files : ['https://cdnjs.cloudflare.com/ajax/libs/moment.js/2.30.1/moment.min.js' ] })
			.then(function() {
				ft3.moment = moment;
				callbackContinue(ntf);
			});
			return;
		}

		// -----------------------------------------------------------------
		// Rule ShowTemplates
		// -----------------------------------------------------------------
		if (
			!ntf.hasRun.showLinkedTemplates
			&& ntf.context.fieldChanged === 'cmdLinkedTemplates'
		) {
			ntf.hasRun.showLinkedTemplates = true;
			ntf.logger.info('In rule ShowTemplates');

			var docId = ntf.document.documentId;
			var uid = ntf.user.documentId;

			var eqry = {
				"sort" : [
					{"name" : "asc"},
					{"systemHeader.summaryName" : "asc"}
				],
				"query": {"bool" : {
					"filter": [
						{"term" : {"systemHeader.systemType" : "template"}}
					],
					"should" : [
						{"term" : {"onLoadClientRuleRel.documentId" : docId}},	
						{"term" : {"onFieldChangeClientRuleRel.documentId" : docId}},	
						{"term" : {"preSaveClientRuleRel.documentId" : docId}},	
						{"term" : {"preSaveServerRuleRel.documentId" : docId}},	
						{"term" : {"postSaveServerRuleRel.documentId" : docId}}   
					],
					"minimum_should_match" : 1
				}}
			};

			ft3.findDocumentsByElastic(eqry, uid, function(err, result) {
				if (err) {
					ft3.ModalService.openModal({
						title : 'Show Linked Templates',
						text : 'ElasticSearch Query error: please check query.',
						type : 'error'
					});
				}
				else {
					var count = result.data.hits.total;

					var arrTemplates = result.data.hits.hits.map(function(hit){return hit._source});
					var arrTitleLinks = arrTemplates.map(function(tdoc) {
						var name = tdoc.name || tdoc.systemHeader.summaryName;
						name = $('<div/>').text(name).html();	   // html-ize it

						var link = '<a href="/form/' + tdoc.documentId + '" target="_blank">'
								+ name + '</a><br/>';
						return link;
					});
					var listz = arrTitleLinks.join('');
					ntf.logger.info('listz ' + listz );

					ft3.ModalService.openModal({
						title : 'Templates using this ruleset',
						html : '# templates linked: <b>' + count + '</b><br/>' + listz,
						type : 'info'
					});

				}
				callbackContinue(ntf);
			});
			return;
		}

		// -----------------------------------------------------------------
		// Rule RunAppTagger2
		// -----------------------------------------------------------------
		if (fieldChanged === 'cmdAppTagger') {
			ntf.logger.info('In rule RunAppTagger2');

			var items = null;

			var stepSequence = {

				// Step 1 - Launch the prompt for appTags, and proceed with sequence.
				start : function() {
					ft3.ModalService.openModal({
						title: "AppTagger",
						text: "Enter appTags to be used:",
						type: "question",

						showCancelButton: true,
						closeOnConfirm: true,
						input : "text",
						inputPlaceholder: "eg: cww,action",
						inputValue : ntf.document.appTaggerTagsCsv || null
					})
					.then(
						function confirmF(value) {
							ntf.logger.info('In confirmF - "' + value + '"');
							stepSequence.fStep002(value);
						},
						function dismissF(dismissType) {
							stepSequence.fStepLast();
						}
					);
				},

				// Step 2 - formulate query on tagsCsv and run query
				fStep002 : function(tagsCsv) {
					ntf.logger.info('fStep002 = ' + tagsCsv);
					if (!tagsCsv || tagsCsv.length === 0) return;

					ntf.document.appTaggerTagsCsv = tagsCsv;

					var tags = tagsCsv.split(',');
					var eqry = {"sort":{"systemHeader.summaryName":"asc"},"query": {"bool": {"filter": [
						{"term" : {"systemHeader.systemType" : "template"}}
					]}}};
					tags.forEach(function(tag) {
						eqry.query.bool.filter.push({"term" : {"appTags" : tag}});
					});

					ft3.findDocumentsByElastic(eqry, ntf.user.documentId, stepSequence.fStep003);

				},

				// Step 3 - Process query results
				fStep003 : function(err,result) {
					ntf.logger.info('fStep003');
					if (err) {
						ft3.showNotification('Error on query: ' + err.message);
						callbackError('Error on query: ' + err.message);
						stepSequence.fStepLast();
					}
					else if (result && result.data && result.data.hits) {
						var display = '';
						var hits = result.data.hits.hits;
						if (hits.length) {
							items = hits.map(function(hit) { 
								var item = {
									'documentId' : hit._source.documentId,
									'name'	  : hit._source.systemHeader.summaryName
								};
								return item;
							});
							var names = items.map(function(item) {return item.name});

							stepSequence.fStep004(names);
						}
					}
					else {
						ft3.ModalService.openModal('', 'No templates found for given appTags', 'error' );
						stepSequence.fStepLast();
					}
				},				

				// Step 4 - confirm replacement of templates and execute
				fStep004 : function(names) {
					ntf.logger.info('fStep004');
					ft3.ModalService.openModal({
						title: "",
						html: "<div style='text-align:left;margin:2em;'>'Templates' will be replaced with the following:" 
								+ "<br/><ul style='text-align:left'><li>" 
								+ names.join('</li><li>') 
								+ '</li></ul></div>',
						type: "warning",
						showCancelButton: true,
						confirmButtonText: "Yes, replace!",
						closeOnConfirm: true
					})
					.then(
						function confirmF() {
							stepSequence.fStep005(true);
						},
						function dismissF() {
							stepSequence.fStepLast();
						}
					);
				},

				// Step 5 - process confirmation
				fStep005 : function(confirm) {
					ntf.logger.info('fStep005');
					if (confirm) {
						ntf.document.template = items;
					}
					stepSequence.fStepLast();
				},

				fStepLast : function() {
					ntf.logger.info('fStepLast');
					ntf.logger.info('Ruleset "Ruleset OnFieldChange" completed ok');
					callbackSuccess();
				}
			};

			stepSequence.start();
			return;
		}

		// -----------------------------------------------------------------
		// Rule LinkTemplates
		// -----------------------------------------------------------------
		if (
			true 
			&& !ntf.hasRun.linkTemplates
			&& ntf.context.fieldChanged === 'cmdLinkOldTemplates'
			&& ntf.document.event
			&& ntf.document.template 
			&& ntf.document.template.length
		) {
			ntf.hasRun.linkTemplates = true;
			ntf.logger.info('In rule LinkTemplates');

			var matrix = {
				'OnLoad'		: 'onLoadClientRuleRel',
				'OnFieldChange' : 'onFieldChangeClientRuleRel',
				'PreSave'	   : 'preSaveClientRuleRel',
				'PreSaveServer' : 'preSaveServerRuleRel',
				'PostSave'	  : 'postSaveServerRuleRel'
			};
			var fieldToChange = ntf.document.event && matrix[ntf.document.event];
			ntf.logger.info('Field To Change : ' + fieldToChange);

			var docIds = ntf.document.template.map(function(item){return item.documentId});
			ntf.logger.info('docIds: ' + docIds);

			var eqry = {"query": {"bool": {"filter": [
				{"terms": {"documentId" : docIds}}	
			]}}}; 
			eqry.size = 1000;

			ft3.findDocumentsByElastic(eqry, ntf.userId, function(err, result) {
				if (err) {
					ntf.logger.error('Error on query: ' + err.message);
					ft3.ModalService.openModal({
						title : "Link Templates",
						text : "Error on query: " + err.message,
						type : 'error'
					});
					callbackContinue(ntf);
					return;
				}
				else if (result && result.data && result.data.hits.total) {
					var templateDocs = result.data.hits.hits.map(function(hit){return hit._source});
					var idx = 0;

					ntf.logger.info('Query ok');
					ntf.logger.info('Results #: ' + templateDocs.length);

					var updateF = function(callback) {
						var tdoc = templateDocs[idx] ;

						ntf.logger.info('Prepping for template: ' + (tdoc.name || tdoc.systemHeader.summaryName))	;
						var eventRSLinks = tdoc[fieldToChange] || [];
						ntf.logger.info('eventRSLinks: ' + JSON.stringify(eventRSLinks));

						// Scan for already existing link
						var linkFound = false;
						eventRSLinks.forEach(function(link) {
							ntf.logger.info('link: ' + JSON.stringify(link));
							if (link.documentId === ntf.document.documentId) {
								linkFound = true;		
							}
						});
						ntf.logger.info('Link found: ' + linkFound);

						// Remove corresponding old embedded rule 
						var oldRuleBlocFound = false;

						var rules = tdoc.rules && tdoc.rules.map(function(item) {
							if (item.name && item.name === ntf.document.event) {
								item.name = ntf.document.event + '-extirpated',
								item.ruleFlow = '/// extirpated ' + ft3.moment().format('YYYY-MM-DD HH:mm:ss') + ' ///';
								oldRuleBlocFound = true;
							}
							return item;
						});
						ntf.logger.info('rules (new) : ' + JSON.stringify(rules));

						var change = {};
						if (!linkFound) {
							eventRSLinks.push({
								documentId : ntf.document.documentId,
								name : ntf.document.systemHeader.summaryName
							});

							ntf.logger.info('eventRSLinks(new): ' + JSON.stringify(eventRSLinks));

							change[fieldToChange] =  eventRSLinks;
						}

						if (oldRuleBlocFound) {
							if (rules && rules.length === 0) {
								rules = null;
							}	
							change.rules = rules
						}

						if (!linkFound || oldRuleBlocFound) {

							ntf.logger.info('Updating: ' + JSON.stringify(change));
							ft3.showNotification('Updating: ' + tdoc.name + '...');

							ft3.updateDocument(tdoc.documentId, change, ntf.userId, function(err, doc) {
								if (err) {
									ntf.logger.error('Error on update: ' + err.message);
								}
								else {
									ntf.logger.info('Target Template updated ok');
								}
								idx += 1;
								if (idx < templateDocs.length) {
									updateF(callback);
								}
								else {
									ntf.logger.info('All target templates updated.');
									callback();
								}
							})
						}
						else {
							ntf.logger.info('Target template "' + tdoc.name + '" already has link.');
							idx += 1;
							if (idx < templateDocs.length) {
								updateF(callback);
							}
							else {
								ntf.logger.info('All target templates updated.');
								callback();
							}
						}
					};

					updateF(function() {
						ntf.logger.info('All Templates updated');
						ft3.ModalService.openModal({
							title : "Link Templates",
							text : "Templates linked successfully.",
							type : "success"
						});
						callbackContinue(ntf);
						return;
					});
				}
				else {
					ft3.ModalService.openModal({
						title : "Link Templates",
						text : "No Templates to link.",
						type : "info"
					});
					callbackContinue(ntf);
					return;
				}
			});
			return
		}

		// -----------------------------------------------------------------
		// Rule GoToRule
		// -----------------------------------------------------------------
		if (
			ntf.context.fieldChanged === 'cmdGoToRule'
			&& !ntf.hasRun.cmdGoToRule
		) {
			ntf.hasRun.cmdGoToRule = true;
			ntf.logger.info('In rule cmdGoToRule');

			var script = ntf.document.ruleSetDSL;
			var jayruleMode = !!script.match(/^\#(include)\s\"JayRule Ruleset Overlay JS/m);
			ntf.logger.info('jayruleMode: ' + jayruleMode);

			var lines = script.split('\n');
			ntf.logger.info('# lines: ' + lines.length);
			var entries = [];
			var subItemExc = 'ruleCondition|ruleAction|ruleItemProcess'.split('|');

			lines.forEach(function(line, index) {
				var ruleNames = line.match(/^\s*rule[A-Z]\w*/);
				if (!jayruleMode) {
					ruleNames = line.match(/^\s*\/\/\s*[Rr]ule\s\w*/);
				}
				if (ruleNames && ruleNames.length && !subItemExc.includes(ruleNames[0].trim())) {
					entries.push( { ruleName : ruleNames[0].trim(), lineNo : (index+1) });		
				}
			});
			ntf.logger.info('entries: ' + JSON.stringify(entries));

			var stylerz =`<style>
			.ruleOption {width:300px;padding:5px;background-color:White;font-size:medium;text-align:left;} 
			.ruleOption:selected {background-color:blue;}
			</style>`;

			var listz = entries.map(e => `<option class='ruleOption' onclick='window.ruleGoLine="${e.lineNo}";'>${('0000' + e.lineNo).slice(-4)} ${e.ruleName}</option>`).join('');
			var selectz = '<select id="ruleGoSelect" size=10>' + listz + '</select>';
			var dlgType = 'info';

			if (entries.length === 0) {
				ft3.ModalService.openModal('Rule Index', 'This ruleset does not have rules defined.', 'error');
			}
			else {
				window.setTimeout(function() {
					ft3.ModalService.openModal({
						title : "Rules",
						html : stylerz + selectz,
						type : 'info',
						showCancelButton : true,
						confirmButtonText : 'Go to Rule'
					})
					.then(
						function confirmF() {
							ntf.logger.info('Going to line ' + window.ruleGoLine);
							var lineNo = parseInt(window.ruleGoLine);

							//editor.scrollToLine(lineNo, true, true, function(){});
							var $mainBox = $('div.mainContent');
							var $mainBox = $('div.simplebar-content-wrapper');
							var $mainBox = $('#ft-sidenav-content');
							var rsePos = $('div[id*="divParentruleSetDSL"]').position();
							var scrollY = $mainBox.scrollTop() + rsePos.top + ((lineNo-1) * 19);

							ntf.logger.info('rsePos.top: ' + rsePos.top);
							ntf.logger.info('scrollY: ' + scrollY);

							ntf.logger.info('Scrolling...');
							ntf.logger.info('$mainBox #: ' + $mainBox.length);

							$mainBox.animate({'scrollTop' : scrollY}, 'slow', function() {
								if (false && ft3.lazyLoader) {
									ft3.lazyLoader.load({name: 'ace', files: ["/vendor/custom-component-modules/ace/ace.js"]})
									.then(function() {	
										var editor = ace.edit('ruleSetDSL');	
										if (editor) {	
											editor.gotoLine(lineNo, 0, true);	
										}	
									});
								}
							});
						},
						function cancelF() {
						}
					);			
				}, 100);
			}
		}

		// -----------------------------------------------------------------
		// Rule LinkToTemplates
		// -----------------------------------------------------------------
		if (
			ntf.context.fieldChanged === 'buttonLinkToTemplates'
			|| ntf.context.fieldChanged === 'buttonHideLinkToTemplates'
		) {
			ntf.logger.info('In rule LinkToTemplates');

			var flag = (ntf.context.fieldChanged === 'buttonLinkToTemplates');

			var fields = [
				'panelTemplateLink',
				'panelTemplateLinkHeader',
				'template',
				'cmdAppTagger',
				'buttonHideLinkToTemplates',
				'buttonClearLinkToTemplates',
				'event',
				'cmdLinkOldTemplates'
			];

			fields.forEach(function(field) {
				ft3.showField(field, flag);
			});
