		}

		// ----------------------------------------------------------------- 
		// Rule AppendUpdatedTag
		// -----------------------------------------------------------------
		ntf.logger.info('ntf.document.flagDslChanged: ' + ntf.document.flagDslChanged);
		if (
			!ntf.hasRun.appendTag
			&& ntf.document.flagDslChanged
			&& !!ft3.moment	  
		) {
			ntf.hasRun.appendTag = true;
			ntf.logger.info('In rule "Append Updated Tag');

			var newLine = '\n';
			var newNameTag = '\/\/ RuleSet: ' + doc.name;
			var newUpdateTag = '\/\/ Updated by: ' + ntf.user.email + ' ' 
					+ ft3.moment().format('YYYY-MM-DD HH:mm:ss Z');

			var rxNameTag = /^\/\/\s*ruleset\:\s*.*$/mi ;
			var rxUpdTag = /^\/\/\s*updated by\:\s*.*$/mi ;

			doc.flagInPreSave = true;

			if (rxUpdTag.test(doc.ruleSetDSL)) {
				ntf.logger.info('Replacing update tag');
				doc.ruleSetDSL = doc.ruleSetDSL.replace(rxUpdTag, newUpdateTag);
			}
			else {
				ntf.logger.info('Prepending update tag');
				doc.ruleSetDSL = newUpdateTag + newLine + doc.ruleSetDSL;
			}

			if (rxNameTag.test(doc.ruleSetDSL)) {
				ntf.logger.info('Replacing name tag');
				doc.ruleSetDSL = doc.ruleSetDSL.replace(rxNameTag, newNameTag);
			}
			else {
				ntf.logger.info('Prepending name tag');
				doc.ruleSetDSL = newNameTag + newLine + doc.ruleSetDSL;
			}
		}

		// -----------------------------------------------------------------
		// Finally
		// -----------------------------------------------------------------
		//delete ntf.document.flagDslChanged;

		ntf.logger.info('Ruleset "RuleSet PreSave" completed ok');		
		callbackSuccess();
	}
}

